/**
 * Highest number ever issued in this project.
 *
 * Archived rows still hold their number, and a number that left with a move
 * is kept on `project_issue_counters`. The next issue continues after both,
 * so a retired number is never issued again.
 */
function readIssuedHighWater(orgId: OrgId, projectId: ProjectId): number {
  const db = getDb();
  const stored = db
    .select({ lastNumber: projectIssueCounters.lastNumber })
    .from(projectIssueCounters)
    .where(
      and(
        orgPredicate(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .get();

  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  return Math.max(stored?.lastNumber ?? 0, row?.value ?? 0);
}

/** Ratchet the per-project high-water mark up to `atLeast`. Never lowers it. */
function rememberIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  atLeast: number,
): void {
  const high = Math.max(readIssuedHighWater(orgId, projectId), atLeast);
  const db = getDb();
  const existing = db
    .select({ lastNumber: projectIssueCounters.lastNumber })
    .from(projectIssueCounters)
    .where(
      and(
        orgPredicate(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .get();

  if (!existing) {
    db.insert(projectIssueCounters)
      .values({ orgId, projectId, lastNumber: high })
      .run();
    return;
  }

  if (existing.lastNumber >= high) return;

  db.update(projectIssueCounters)
    .set({ lastNumber: high })
    .where(
      and(
        orgPredicate(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .run();
}

