/**
 * Moves an issue onto `toProjectId` and gives it that project's next number.
 * The number it leaves behind is retired first, while the row still holds it,
 * so a later issue in the source project cannot take it. Title, description,
 * status, priority, assignee, estimate, due date, labels and links are left
 * as they are. Moving onto the project the issue is already in is a no-op.
 */
export async function transferIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  const current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  if (current.projectId === toProjectId) {
    const labels = await listLabelsForIssues(orgId, [issueId]);
    return toIssue(current, (labels[issueId] ?? []).map((label) => label.id));
  }

  const fromProjectId = current.projectId as ProjectId;
  rememberIssuedNumber(orgId, fromProjectId, current.number);
  const toNumber = readIssuedHighWater(orgId, toProjectId) + 1;

  const row = db
    .update(issues)
    .set({
      projectId: toProjectId,
      number: toNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  rememberIssuedNumber(orgId, toProjectId, toNumber);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

