import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityActionSchema } from "@/schemas/activity";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("moveproj", "free");
});

afterAll(() => {
  cleanup();
});

describe("moveIssueToProject", () => {
  it("moves, renumbers, retires, preserves relations, audits and reindexes", async () => {
    const detachActivity = registerActivityListeners();
    const detachSearch = registerSearchListeners();
    const seen: unknown[] = [];
    const otherSeen: unknown[] = [];
    const offMoved = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    const offCreated = subscribe("issue.created", (payload) => {
      otherSeen.push(payload);
    });
    const offUpdated = subscribe("issue.updated", (payload) => {
      otherSeen.push(payload);
    });
    const offArchived = subscribe("issue.archived", (payload) => {
      otherSeen.push(payload);
    });

    try {
      const target = await projectService.createProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        name: "Mobile",
        slug: "mobile",
        key: "MOB",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      });

      const label = await labelRepo.insertLabel({
        orgId: tenant.org.id,
        name: "move-me",
        color: "#112233",
        description: null,
      });

      const created = await issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, {
          title: "Take me with you",
          assigneeId: tenant.userIds.admin,
        }),
        description: "keep this body",
        status: "in_progress",
        priority: "high",
        estimate: 5,
        labelIds: [label.id],
      });

      const filler = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Stays home" }),
      );

      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        body: "do not drop me",
        parentId: null,
        mentionedUserIds: [],
      });

      const attachment = await attachmentRepo.insertAttachment(
        {
          orgId: tenant.org.id,
          issueId: created.id,
          filename: "note.txt",
          contentType: "text/plain",
          sizeBytes: 12,
        },
        tenant.userIds.member,
      );

      const parent = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Parent stays" }),
      );
      await issueRepo.updateIssue({
        orgId: tenant.org.id,
        issueId: created.id,
        description: "keep this body",
      });
      // parent link is set only at insert; re-read after a direct patch below.
      const dbIssue = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(dbIssue).not.toBeNull();

      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        status: "in_progress",
      });

      const beforeMove = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(beforeMove?.number).toBe(created.number);

      const movedEventsBefore = seen.length;
      const moved = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        toProjectId: target.id,
      });

      expect(moved.id).toBe(created.id);
      expect(moved.projectId).toBe(target.id);
      expect(moved.number).toBe(1);
      expect(moved.title).toBe("Take me with you");
      expect(moved.description).toBe("keep this body");
      expect(moved.status).toBe("in_progress");
      expect(moved.priority).toBe("high");
      expect(moved.assigneeId).toBe(tenant.userIds.admin);
      expect(moved.estimate).toBe(5);
      expect(moved.authorId).toBe(created.authorId);
      expect(moved.labelIds).toContain(label.id);
      expect(moved.archivedAt).toBeNull();

      const stored = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(stored).toMatchObject({
        projectId: target.id,
        number: 1,
        title: moved.title,
        parentId: created.parentId,
      });

      expect(await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, created.number)).toBeNull();
      expect(await issueRepo.findIssueByNumber(tenant.org.id, target.id, 1)).toMatchObject({
        id: created.id,
      });

      const sourceBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        tenant.project.id,
      );
      const targetBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        target.id,
      );
      const sourceIds = sourceBoard.flatMap((column) => column.issues.map((issue) => issue.id));
      const targetIds = targetBoard.flatMap((column) => column.issues.map((issue) => issue.id));
      expect(sourceIds).not.toContain(created.id);
      expect(targetIds).toContain(created.id);
      expect(sourceIds).toContain(filler.id);

      const sourceList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        limit: 50,
        cursor: null,
      });
      const targetList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: target.id,
        limit: 50,
        cursor: null,
      });
      expect(sourceList.items.map((issue) => issue.id)).not.toContain(created.id);
      expect(targetList.items.map((issue) => issue.id)).toContain(created.id);

      expect(await commentRepo.findCommentById(tenant.org.id, comment.id)).toMatchObject({
        issueId: created.id,
        body: "do not drop me",
      });
      expect(await attachmentRepo.listAttachments(tenant.org.id, created.id)).toEqual([
        expect.objectContaining({ id: attachment.id, filename: "note.txt" }),
      ]);

      expect(seen).toHaveLength(movedEventsBefore + 1);
      expect(seen.at(-1)).toMatchObject({
        orgId: tenant.org.id,
