describe("moveIssueToProject", () => {
  it("moves, renumbers, retires, preserves relations, audits and reindexes", async () => {
    const detachActivity = registerActivityListeners();
    const detachSearch = registerSearchListeners();
    const seen: unknown[] = [];
    const otherSeen: unknown[] = [];
    const offMoved = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    const offCreated = subscribe("issue.created", (payload) => {
      otherSeen.push(payload);
    });
    const offUpdated = subscribe("issue.updated", (payload) => {
      otherSeen.push(payload);
    });
    const offArchived = subscribe("issue.archived", (payload) => {
      otherSeen.push(payload);
    });

    try {
      const target = await projectService.createProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        name: "Mobile",
        slug: "mobile",
        key: "MOB",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      });

      const label = await labelRepo.insertLabel({
        orgId: tenant.org.id,
        name: "move-me",
        color: "#112233",
        description: null,
      });

      const created = await issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, {
          title: "Take me with you",
          assigneeId: tenant.userIds.admin,
        }),
        description: "keep this body",
        status: "in_progress",
        priority: "high",
        estimate: 5,
        labelIds: [label.id],
      });

      const filler = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Stays home" }),
      );

      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        body: "do not drop me",
        parentId: null,
        mentionedUserIds: [],
      });

      const attachment = await attachmentRepo.insertAttachment(
        {
          orgId: tenant.org.id,
          issueId: created.id,
          filename: "note.txt",
          contentType: "text/plain",
          sizeBytes: 12,
        },
        tenant.userIds.member,
      );

      const parent = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Parent stays" }),
      );
      await issueRepo.updateIssue({
        orgId: tenant.org.id,
        issueId: created.id,
        description: "keep this body",
      });
      // parent link is set only at insert; re-read after a direct patch below.
      const dbIssue = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(dbIssue).not.toBeNull();

      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        status: "in_progress",
      });

      const beforeMove = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(beforeMove?.number).toBe(created.number);

      const movedEventsBefore = seen.length;
      const moved = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: created.id,
        toProjectId: target.id,
      });

      expect(moved.id).toBe(created.id);
      expect(moved.projectId).toBe(target.id);
      expect(moved.number).toBe(1);
      expect(moved.title).toBe("Take me with you");
      expect(moved.description).toBe("keep this body");
      expect(moved.status).toBe("in_progress");
      expect(moved.priority).toBe("high");
      expect(moved.assigneeId).toBe(tenant.userIds.admin);
      expect(moved.estimate).toBe(5);
      expect(moved.authorId).toBe(created.authorId);
      expect(moved.labelIds).toContain(label.id);
      expect(moved.archivedAt).toBeNull();

      const stored = await issueRepo.findIssueById(tenant.org.id, created.id);
      expect(stored).toMatchObject({
        projectId: target.id,
        number: 1,
        title: moved.title,
        parentId: created.parentId,
      });

      expect(await issueRepo.findIssueByNumber(tenant.org.id, tenant.project.id, created.number)).toBeNull();
      expect(await issueRepo.findIssueByNumber(tenant.org.id, target.id, 1)).toMatchObject({
        id: created.id,
      });

      const sourceBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        tenant.project.id,
      );
      const targetBoard = await issueService.getBoard(
        tenant.actors.member,
        tenant.org.id,
        target.id,
      );
      const sourceIds = sourceBoard.flatMap((column) => column.issues.map((issue) => issue.id));
      const targetIds = targetBoard.flatMap((column) => column.issues.map((issue) => issue.id));
      expect(sourceIds).not.toContain(created.id);
      expect(targetIds).toContain(created.id);
      expect(sourceIds).toContain(filler.id);

      const sourceList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        limit: 50,
        cursor: null,
      });
      const targetList = await issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: target.id,
        limit: 50,
        cursor: null,
      });
      expect(sourceList.items.map((issue) => issue.id)).not.toContain(created.id);
      expect(targetList.items.map((issue) => issue.id)).toContain(created.id);

      expect(await commentRepo.findCommentById(tenant.org.id, comment.id)).toMatchObject({
        issueId: created.id,
        body: "do not drop me",
      });
      expect(await attachmentRepo.listAttachments(tenant.org.id, created.id)).toEqual([
        expect.objectContaining({ id: attachment.id, filename: "note.txt" }),
      ]);

      expect(seen).toHaveLength(movedEventsBefore + 1);
      expect(seen.at(-1)).toMatchObject({
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        issueId: created.id,
        fromProjectId: tenant.project.id,
        toProjectId: target.id,
        fromNumber: created.number,
        toNumber: 1,
      });
      expect(otherSeen.filter((event) => {
        const payload = event as { issueId?: string };
        return payload.issueId === created.id;
      })).toEqual([]);

      const audit = await activityRepo.listActivity({
        orgId: tenant.org.id,
        action: ["issue.moved"],
        limit: 20,
        cursor: null,
      });
      expect(audit.items).toHaveLength(1);
      expect(audit.items[0]).toMatchObject({
        action: "issue.moved",
        actorId: tenant.userIds.member,
        subjectKind: "issue",
        subjectId: created.id,
        projectId: target.id,
        metadata: {
          fromProjectId: tenant.project.id,
          toProjectId: target.id,
          fromNumber: created.number,
          toNumber: 1,
        },
      });

      const prior = await activityRepo.listActivityForSubject(
        tenant.org.id,
        "issue",
        created.id,
      );
      const createdRow = prior.find((event) => event.action === "issue.created");
      expect(createdRow?.projectId).toBe(tenant.project.id);

      const targetHits = await search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Take me with you",
        kinds: ["issue"],
        projectId: target.id,
        limit: 10,
        cursor: null,
      });
      const sourceHits = await search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Take me with you",
        kinds: ["issue"],
        projectId: tenant.project.id,
        limit: 10,
        cursor: null,
      });
      expect(targetHits.items.map((hit) => hit.id)).toContain(created.id);
      expect(sourceHits.items.map((hit) => hit.id)).not.toContain(created.id);

      const nextSource = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      expect(nextSource).toBeGreaterThan(filler.number);
      expect(nextSource).toBeGreaterThan(created.number);
      const born = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "After the move" }),
      );
      expect(born.number).toBe(nextSource);
      expect(born.number).not.toBe(created.number);

      const same = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: moved.id,
        toProjectId: target.id,
      });
      expect(same.number).toBe(moved.number);
      expect(same.projectId).toBe(target.id);
      expect(seen).toHaveLength(movedEventsBefore + 1);
      const auditAfterSame = await activityRepo.listActivity({
        orgId: tenant.org.id,
        action: ["issue.moved"],
        limit: 20,
        cursor: null,
      });
      expect(auditAfterSame.items).toHaveLength(1);

      const back = await issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: moved.id,
        toProjectId: tenant.project.id,
      });
      expect(back.projectId).toBe(tenant.project.id);
      expect(back.number).not.toBe(created.number);
      expect(back.number).toBeGreaterThan(born.number);
      expect(back.title).toBe(moved.title);
      expect(back.labelIds).toContain(label.id);

      const nextTarget = await issueRepo.nextIssueNumber(tenant.org.id, target.id);
      expect(nextTarget).toBe(2);

      void parent;
    } finally {
      offMoved();
      offCreated();
      offUpdated();
      offArchived();
      detachActivity();
      detachSearch();
    }
  });

  it("refuses without edit or create permission and leaves the row", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Permission gate" }),
    );
    const target = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const still = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(still).toMatchObject({ projectId: tenant.project.id, number: issue.number });
  });

  it("refuses an archived issue and an archived target without writing", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived source" }),
    );
    const archivedTarget = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Old",
      slug: "old",
      key: "OLD",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, tenant.org.id, archivedTarget.id);

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: archivedTarget.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toMatchObject({
      projectId: tenant.project.id,
      number: issue.number,
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const liveTarget = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Fresh",
      slug: "fresh",
      key: "FRS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: liveTarget.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("applies the target project quota and changes nothing when refused", async () => {
    const full = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Full",
      slug: "full",
      key: "FUL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, full.id, { title: `Full ${number}` }),
        tenant.userIds.member,
        number,
      );
    }
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Does not fit" }),
    );
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    try {
      await expect(
        issueService.moveIssueToProject(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          toProjectId: full.id,
        }),
      ).rejects.toThrow(/allows no more issues/);
    } finally {
      off();
    }
    expect(seen).toHaveLength(0);
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toMatchObject({
      projectId: tenant.project.id,
      number: issue.number,
    });
    expect(await issueRepo.countIssues(tenant.org.id, full.id)).toBe(100);
  });

  it("accepts issue.moved on the audit filter schema", () => {
    expect(activityActionSchema.safeParse("issue.moved").success).toBe(true);
    const parsed = moveIssueToProjectSchema.parse({
      orgId: tenant.org.id,
      issueId: tenant.project.id,
      toProjectId: tenant.project.id,
    });
    expect(parsed.toProjectId).toBe(tenant.project.id);
  });
});
